const items = $input.all();

const image1Text = items[0]?.json?.content?.parts?.[0]?.text || '';
const image2Text = items[1]?.json?.content?.parts?.[0]?.text || '';

const binaries = {};

// Collect all binary files dynamically
items.forEach(item => {
  if (item.binary) {
    Object.entries(item.binary).forEach(([key, value]) => {
      binaries[key] = value;
    });
  }
});

return [
  {
    json: {
      image1Description: image1Text,
      image2Description: image2Text
    },
    binary: binaries
  }
];

const items = $input.all();

const outJson = {};
const outBinary = {};

let textIndex = 1;
let imageIndex = 1;

items.forEach((item) => {

  // -------- TEXT ----------
  const text = item.json?.content?.parts?.[0]?.text;
  if (text) {
    outJson[`image${textIndex}Description`] = text;
    textIndex++;
  }

  // -------- BINARY ----------
  if (item.binary) {
    Object.entries(item.binary).forEach(([key, value]) => {
      outBinary[`image_${imageIndex}`] = value;
      imageIndex++;
    });
  }

});

return [
  {
    json: outJson,
    binary: outBinary
  }
];
